import * as THREE from 'three/webgpu';
import { texture, uv, color, uniform, vec3, mix, step, positionLocal, float } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-row';

  const pos = config.scenePosition ?? { x: 0, y: 0.7, z: 0 };
  const rot = config.sceneRotation ?? { x: 0, y: 0, z: 0 };
  const scl = config.sceneScale ?? { x: 1, y: 1, z: 1 };
  group.position.set(pos.x, pos.y, pos.z);
  group.rotation.set(rot.x, rot.y, rot.z);
  group.scale.set(scl.x, scl.y, scl.z);

  const colors = {
    ink: new THREE.Color('#16161d'),
    paper: new THREE.Color('#e8ecf2'),
    accent: new THREE.Color('#ff2a38'),
    surface: new THREE.Color('#0b0b10')
  };

  const width = 6.5;
  const height = 0.5;

  // background plane with brushed metal texture
  const map = ctx.textureLoader.load('/prism-assets/chrome/brushed-metal.map.png');
  map.colorSpace = THREE.SRGBColorSpace;

  const hoverUniform = uniform(0.0);
  const focusUniform = uniform(0.0);

  const material = new THREE.MeshBasicNodeMaterial({ transparent: true });
  const baseTex = texture(map, uv());
  const surfaceColor = color(colors.surface);
  const tinted = mix(surfaceColor, baseTex, float(0.35));

  const accentEdge = step(0.985, uv().x).mul(focusUniform);
  const finalColor = mix(tinted, color(colors.accent), accentEdge);
  material.colorNode = finalColor;
  material.opacityNode = float(0.92).add(hoverUniform.mul(0.08));

  const geometry = new THREE.PlaneGeometry(width, height);
  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'hub-collection-row-bg';
  group.add(plane);

  // divider line (thin plane at bottom edge)
  const dividerMat = new THREE.MeshBasicNodeMaterial({ transparent: true });
  dividerMat.colorNode = color(colors.paper);
  dividerMat.opacityNode = float(0.18);
  const dividerGeo = new THREE.PlaneGeometry(width * 0.96, 0.01);
  const divider = new THREE.Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -height / 2 + 0.01, 0.001);
  divider.name = 'hub-collection-row-divider';
  group.add(divider);

  // title text
  const titleMesh = createTextMesh({
    text: 'Title',
    font: 'JetBrains Mono',
    weight: 700,
    size: 0.13,
    color: colors.paper,
    atlas: ctx.fontAtlas,
    maxWidth: width * 0.5
  });
  titleMesh.position.set(-width / 2 + 0.25, 0.02, 0.002);
  titleMesh.name = 'row-title-text';
  group.add(titleMesh);

  // meta text
  const metaMesh = createTextMesh({
    text: 'Meta',
    font: 'JetBrains Mono',
    weight: 400,
    size: 0.09,
    color: colors.paper.clone().lerp(new THREE.Color('#000000'), 0.15),
    atlas: ctx.fontAtlas,
    maxWidth: width * 0.3
  });
  metaMesh.position.set(width / 2 - 1.2, 0.02, 0.002);
  metaMesh.name = 'row-meta-text';
  group.add(metaMesh);

  const baseY = pos.y;
  let hoverTl = null;
  let pressTl = null;

  const handlers = {
    hover: () => {
      hoverUniform.value = 1.0;
      focusUniform.value = 1.0;
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, {
        y: baseY + 0.15,
        duration: 0.7,
        ease: 'power3.out'
      });
    },
    unhover: () => {
      hoverUniform.value = 0.0;
      focusUniform.value = 0.0;
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(group.position, {
        y: baseY,
        duration: 0.7,
        ease: 'power3.out'
      });
    },
    click: (event) => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline();
      pressTl.to(group.scale, {
        x: scl.x * 0.97,
        y: scl.y * 0.97,
        z: scl.z * 0.97,
        duration: 0.12,
        ease: 'back.out'
      }).to(group.scale, {
        x: scl.x,
        y: scl.y,
        z: scl.z,
        duration: 0.15,
        ease: 'back.out'
      });

      if (ctx.emit) {
        ctx.emit('hub-collection.select', { source: group.name, event });
      }
    }
  };

  group.userData.handlers = handlers;

  group.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    geometry.dispose();
    dividerGeo.dispose();
    material.dispose();
    dividerMat.dispose();
    if (map) map.dispose();
    if (titleMesh.geometry) titleMesh.geometry.dispose();
    if (titleMesh.material) titleMesh.material.dispose();
    if (metaMesh.geometry) metaMesh.geometry.dispose();
    if (metaMesh.material) metaMesh.material.dispose();
  };

  return group;
}
